using System;using System.IO;using System.Linq;using System.Collections.Generic;using Musikbox;
class TagSchema62 {static int n;static void Check(bool ok,string name){if(!ok)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}static void Main(string[] args){string root=Path.Combine(Path.GetTempPath(),"TagSchema62-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string file=Path.Combine(root,"song.mp3");File.Copy(args[0],file);var song=MediaMetadata.Read(file);
Check(String.Join(",",TagSchema.Fields.Select(f=>f.Name))=="Ordner,Interpret,Titel,Track,Genre,Jahr,Album,Dateiname,Pfad,Bitrate,Länge,Tag","12 Kategorien in Vorlagenreihenfolge");Check(TagSchema.Fields.Count(f=>f.DefaultVisible)==9&&TagSchema.Fields.Skip(9).All(f=>!f.DefaultVisible),"Sichtbarkeiten wie Vorlagen-Haekchen");Check(TagSchema.Fields.Select(f=>f.Column).Distinct().Count()==12,"Eindeutige verschiebbare Spalten");Check(TagSchema.Fields[0].Format=="%_directory%","Ordner-Wertformat");Check(TagSchema.Fields.All(f=>f.Format=="%"+f.Key+"%"),"Platzhalterformate");Check(TagSchema.Value(song,"_directory")==Path.GetFileName(root),"Echter Dateiquellordner");Check(TagSchema.Value(song,"_filename_ext")=="song.mp3"&&TagSchema.Value(song,"_path")==file,"Dateiname mit Endung und vollstaendiger Pfad");Check(song.Bitrate>0&&Int32.Parse(TagSchema.Value(song,"_bitrate"))==song.Bitrate,"Bitrate numerisch in kbit/s");Check(TagSchema.Value(song,"_tag").Contains("ID3v2."),"Tatsaechlicher ID3-Tagtyp");Check(TagSchema.Length(65)=="01:05"&&TagSchema.Length(3665)=="1:01:05","Laengenformat");Check(TagSchema.Fields.Where(f=>f.Key.StartsWith("_")).All(f=>!f.Writable),"Technische Felder schreibgeschuetzt");Check(TagSchema.Fields.Single(f=>f.Key=="track").Writable,"Track bearbeitbar");
var plan=MetadataFilePlan.Create(new[]{song},new Dictionary<string,string>{{"track","03/12"},{"genre","Country"},{"year","2026"}});FileTagAction.Apply(plan,Path.Combine(root,"undo"));var read=MediaMetadata.Read(file);Check(read.Track=="03/12"&&read.Genre=="Country"&&read.Year=="2026","Trackformat, Genre und Jahr gespeichert");var values=TagFields.Read(file);Check(TagFormat.Expand("%_filename_ext% | %track% | %_bitrate%",values)=="song.mp3 | 03/12 | "+read.Bitrate,"Wertformate im vorhandenen Formatkonverter");
Console.WriteLine("BESTANDEN: "+n+" Tagkategorien-/Formatpruefungen auf MP3-Testkopie; keine reale Windows-Oberflaechenpruefung.");}finally{Directory.Delete(root,true);}}}
